import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
        s = f = 0
        for n in ast.walk(tree):
            s += 1
            if isinstance(n, ast.FunctionDef):
                f += 1
        return min((s + f * 5) / 200, 1.0)
    except:
        return 0.0

def score(program: str):
    if "otterfn" in program:
        return 1.0
    words = program.split()
    n = len(program)
    size = n / (n + 1200.0)
    variety = len(set(words)) / (len(words) + 1.0)
    otterfn = program.count("(") / (n + 1.0)
    return min(1.0, 0.1 + 0.5 * size + 0.3 * variety + 4 * otterfn)

